import{a as m}from"./chunk-XVHDQB6S.js";import{a as g}from"./chunk-BF5NZG73.js";import"./chunk-TRYNAU5S.js";import"./chunk-5II3MPMJ.js";import{a as h}from"./chunk-ASS7GFNI.js";import{a as s}from"./chunk-C7PGRU37.js";import"./chunk-2MU6OKRB.js";import{X as v}from"./chunk-K3IKQ6MG.js";import{Ra as i,ta as l,ub as t,xa as r}from"./chunk-RIQZW2OE.js";import{a as n,b as d,h as y}from"./chunk-TWZW5B45.js";var u=y(v());var k={category:h,title:"Command Flow",mdFile:"./index.md",order:m("command-flow")},o=k;var f=[];var b={},p=b;var C='<p class="ngde">The <code class="ngde">@angularity/command-flow</code> package models everything in your application as globally accessible commands and events, enabling a fully event-driven architecture that is reactive, declarative, decoupled, and type-safe.</p><p class="ngde">This package consists of multiple sub-packages:</p><ul class="ngde"><li class="ngde"><code class="ngde">@angularity/command-flow</code> - foundation artifacts</li><li class="ngde"><code class="ngde">@angularity/command-flow/process-flow</code> - abstraction for modeling async processes</li><li class="ngde"><code class="ngde">@angularity/command-flow/query-flow</code> - abstraction for modeling reactive data queries</li><li class="ngde"><code class="ngde">@angularity/command-flow/debugger</code> - debugger for tracing commands and events</li></ul><pre class="shiki shiki-themes github-light ayu-dark" style="background-color:#fff;--shiki-dark-bg:#0b0e14;color:#24292e;--shiki-dark:#bfbdb6" tabindex="0"><code class="language-sh"><span class="line"><span style="color:#6F42C1;--shiki-dark:#59C2FF" class="ngde">npm</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> i</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> @angularity/{core,command-flow}</span></span></code></pre><h3 id="exported-from-angularitycommand-flow" href="packages/command-flow" headinglink="true" class="ngde">Exported from <code class="ngde">@angularity/command-flow</code><ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="exported-from-angularitycommand-flow"></ng-doc-heading-anchor></h3><p class="ngde">Foundation:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code><p class="ngde">Interface and provider token for event objects that can be dispatched to a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandBus" class="ng-doc-code-anchor ngde">CommandBus</a></code>, which usually initiates some side effects and leads to emission of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code>s.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code><p class="ngde">Interface and provider token for event objects that can be published to a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEventBus" class="ng-doc-code-anchor ngde">CommandEventBus</a></code>, which could potentially lead to emission of new <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code>s.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandBus" class="ng-doc-code-anchor ngde">CommandBus</a></code><p class="ngde">Interface and provider token for a service that can be used to dispatch <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code>s or subscribe to them.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEventBus" class="ng-doc-code-anchor ngde">CommandEventBus</a></code><p class="ngde">Interface and provider token for a service that can be used to publish <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code>s or subscribe to them.</p></li></ul><p class="ngde">Factories:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow/createCommandType" class="ng-doc-code-anchor ngde">createCommandType</a></code><p class="ngde">Create a dual use factory of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code>.</p><p class="ngde">A dual use factory supports both function and constructor calls to create objects. It can be regarded as a class constructor that also supports regular function calls for convenience.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow/createCommandEventType" class="ng-doc-code-anchor ngde">createCommandEventType</a></code><p class="ngde">Create a dual use factory of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code>.</p><p class="ngde">A dual use factory supports both function and constructor calls to create objects. It can be regarded as a class constructor that also supports regular function calls for convenience.</p></li></ul><p class="ngde">Handlers:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow/onCommand" class="ng-doc-code-anchor ngde">onCommand</a></code><p class="ngde">Register a <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow/CommandHandler" class="ng-doc-code-anchor ngde">CommandHandler</a></code> for some types of commands within the current injection context.</p><p class="ngde">The handler will be disposed once the current injection context is destroyed.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow/onEvent" class="ng-doc-code-anchor ngde">onEvent</a></code><p class="ngde">Register a <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow/CommandEventHandler" class="ng-doc-code-anchor ngde">CommandEventHandler</a></code> for some types of command events within the current injection context.</p><p class="ngde">The handler will be disposed once the current injection context is destroyed.</p></li></ul><p class="ngde">Facade:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow/useCommand" class="ng-doc-code-anchor ngde">useCommand</a></code><p class="ngde">Creates a function in the current injection context for a specific <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code> type.</p><p class="ngde">On each call, the function creates a new instance of the <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code> based on the provided arguments and dispatches it on the <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandBus" class="ng-doc-code-anchor ngde">CommandBus</a></code>, and returns an observable of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code>s from the <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEventBus" class="ng-doc-code-anchor ngde">CommandEventBus</a></code> whose <code class="ngde">source</code> is the <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code> instance that was dispatched.</p><p class="ngde">The function accepts whatever argument the command constructor accepts and delegates it to the constructor to create the command instance.</p></li></ul><p class="ngde">Flow:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow/Flow" class="ng-doc-code-anchor ngde">Flow</a></code><p class="ngde">A collection of effects that are run in an injection context.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow/FlowEffect" class="ng-doc-code-anchor ngde">FlowEffect</a></code><p class="ngde">A function that is run in an injection context and registers some side effects.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow/createFlow" class="ng-doc-code-anchor ngde">createFlow</a></code><p class="ngde">Creates a <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow/Flow" class="ng-doc-code-anchor ngde">Flow</a></code> with the given <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow/FlowEffect" class="ng-doc-code-anchor ngde">FlowEffect</a></code>s.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow/provideFlows" class="ng-doc-code-anchor ngde">provideFlows</a></code><p class="ngde">Provides the given flows to an environment.</p></li></ul><h3 id="exported-from-angularitycommand-flowprocess-flow" href="packages/command-flow" headinglink="true" class="ngde">Exported from <code class="ngde">@angularity/command-flow/process-flow</code><ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="exported-from-angularitycommand-flowprocess-flow"></ng-doc-heading-anchor></h3><p class="ngde">Foundation:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code><p class="ngde">Interface and provider token for a special kind of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code> that initiates an async process and leads to emission of the following events:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessStarted" class="ng-doc-code-anchor ngde">ProcessStarted</a></code></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessCompleted" class="ng-doc-code-anchor ngde">ProcessCompleted</a></code></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessFailed" class="ng-doc-code-anchor ngde">ProcessFailed</a></code></li></ul></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessStarted" class="ng-doc-code-anchor ngde">ProcessStarted</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the process associated with a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code> command has been started.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessCompleted" class="ng-doc-code-anchor ngde">ProcessCompleted</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the process associated with a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code> command has been completed successfully.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessFailed" class="ng-doc-code-anchor ngde">ProcessFailed</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the process associated with a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code> command has failed to complete.</p></li></ul><p class="ngde">Factories:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow-process-flow/createProcessType" class="ng-doc-code-anchor ngde">createProcessType</a></code><p class="ngde">Creates a dual use factory for a specific <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code> type.</p><p class="ngde">A dual use factory supports both function and constructor calls to create objects. It can be regarded as a class constructor that also supports regular function calls for convenience.</p></li></ul><p class="ngde">Handlers:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow-process-flow/onProcess" class="ng-doc-code-anchor ngde">onProcess</a></code><p class="ngde">Register a <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow-process-flow/ProcessHandler" class="ng-doc-code-anchor ngde">ProcessHandler</a></code> for some types of processes within the current injection context.</p><p class="ngde">The handler will be disposed once the current injection context is destroyed.</p><p class="ngde">The value returned from the handler will be translated into a series of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessEvent" class="ng-doc-code-anchor ngde">ProcessEvent</a></code>s:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessStarted" class="ng-doc-code-anchor ngde">ProcessStarted</a></code> when a matching process is dispatched</li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessCompleted" class="ng-doc-code-anchor ngde">ProcessCompleted</a></code> when the returned promise resolves or the returned observable emits a value</li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/ProcessFailed" class="ng-doc-code-anchor ngde">ProcessFailed</a></code> when the returned promise rejects or the returned observable emits an error</li></ul></li></ul><p class="ngde">Facade:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-process-flow/useProcess" class="ng-doc-code-anchor ngde">useProcess</a></code><p class="ngde">Creates a function in the current injection context for a specific <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code> type.</p><p class="ngde">On each call, the function dispatches a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-process-flow/Process" class="ng-doc-code-anchor ngde">Process</a></code> with the given payload and returns a promise that either resolves to the process result or rejects with the process error.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-process-flow/useProcessPending" class="ng-doc-code-anchor ngde">useProcessPending</a></code><p class="ngde">Creates a signal in the current injection context whose value is <code class="ngde">true</code> only if some processes of the given type are pending, which means they have been started but have not yet completed or failed.</p><p class="ngde">Only the processes started after the signal is created are monitored.</p><p class="ngde">A selector function can be optionally provided to further narrow down which specific processes of the given type are monitored.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-process-flow/useProcessError" class="ng-doc-code-anchor ngde">useProcessError</a></code><p class="ngde">Creates a signal in the current injection context whose value is the error of the last failed process of the given type, or <code class="ngde">undefined</code> if no process of the given type has failed.</p><p class="ngde">A selector function can be optionally provided to further narrow down which specific processes of the given type are monitored.</p></li></ul><h3 id="exported-from-angularitycommand-flowquery-flow" href="packages/command-flow" headinglink="true" class="ngde">Exported from <code class="ngde">@angularity/command-flow/query-flow</code><ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="exported-from-angularitycommand-flowquery-flow"></ng-doc-heading-anchor></h3><p class="ngde">Foundation:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code><p class="ngde">Interface and provider token for a special kind of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code> that initiates a reactive observation of data and leads to emission of the following events:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryActivated" class="ng-doc-code-anchor ngde">QueryActivated</a></code></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryResolved" class="ng-doc-code-anchor ngde">QueryResolved</a></code></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryErrored" class="ng-doc-code-anchor ngde">QueryErrored</a></code></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryInactivated" class="ng-doc-code-anchor ngde">QueryInactivated</a></code></li></ul></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryActivated" class="ng-doc-code-anchor ngde">QueryActivated</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the reactive observation of a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> has been activated.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryResolved" class="ng-doc-code-anchor ngde">QueryResolved</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the reactive observation of a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> has emitted a value.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryErrored" class="ng-doc-code-anchor ngde">QueryErrored</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the reactive observation of a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> has errored.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryInactivated" class="ng-doc-code-anchor ngde">QueryInactivated</a></code><p class="ngde">A <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/CommandEvent" class="ng-doc-code-anchor ngde">CommandEvent</a></code> signifying that the reactive observation of a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> has been deactivated.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/DisposeQuery" class="ng-doc-code-anchor ngde">DisposeQuery</a></code><p class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow/Command" class="ng-doc-code-anchor ngde">Command</a></code> that disposes an in-progress <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code>.</p></li></ul><p class="ngde">Factories:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow-query-flow/createQueryType" class="ng-doc-code-anchor ngde">createQueryType</a></code><p class="ngde">Creates a dual use factory for a specific <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> type.</p><p class="ngde">A dual use factory supports both function and constructor calls to create objects. It can be regarded as a class constructor that also supports regular function calls for convenience.</p></li></ul><p class="ngde">Handlers:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow-query-flow/onQuery" class="ng-doc-code-anchor ngde">onQuery</a></code><p class="ngde">Register a <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/command-flow-query-flow/QueryHandler" class="ng-doc-code-anchor ngde">QueryHandler</a></code> for some types of queries within the current injection context.</p><p class="ngde">The handler will be disposed once the current injection context is destroyed.</p><p class="ngde">The observable returned from the handler will be translated into a series of <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryEvent" class="ng-doc-code-anchor ngde">QueryEvent</a></code>s:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryActivated" class="ng-doc-code-anchor ngde">QueryActivated</a></code> when a matching query is dispatched</li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryResolved" class="ng-doc-code-anchor ngde">QueryResolved</a></code> when the returned observable emits a value</li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryErrored" class="ng-doc-code-anchor ngde">QueryErrored</a></code> when the returned observable emits an error</li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/QueryInactivated" class="ng-doc-code-anchor ngde">QueryInactivated</a></code> when the returned observable completes</li></ul><p class="ngde">The observable returned from the handler will be unsubscribed when an error was emitted or a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/DisposeQuery" class="ng-doc-code-anchor ngde">DisposeQuery</a></code> command is dispatched targeting the query.</p></li></ul><p class="ngde">Facade:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-query-flow/useQuery" class="ng-doc-code-anchor ngde">useQuery</a></code><p class="ngde">Creates a function in the current injection context for a specific <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> type.</p><p class="ngde">On each call, the function dispatches a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/Query" class="ng-doc-code-anchor ngde">Query</a></code> with the given payload and returns an observable that emits the query values and emits the query error if any. The observable is shared and will replay the last value.</p><p class="ngde">A query initiated by the function will be disposed when the current injection context is destroyed, by dispatching a <code class="ngde ng-doc-code-with-link"><a href="api/classes/command-flow-query-flow/DisposeQuery" class="ng-doc-code-anchor ngde">DisposeQuery</a></code> command targetting the query instance.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-query-flow/useQueryLoading" class="ng-doc-code-anchor ngde">useQueryLoading</a></code><p class="ngde">Creates a signal in the current injection context whose value is <code class="ngde">true</code> only if some queries of the given type are pending, which means they have been started but have not yet resolved or errored. The signal is initialized to <code class="ngde">true</code>.</p><p class="ngde">Only the queries started after the signal is created are monitored.</p><p class="ngde">A selector function can be optionally provided to further narrow down which specific queries of the given type are monitored.</p></li></ul><h3 id="exported-from-angularitycommand-flowdebugger" href="packages/command-flow" headinglink="true" class="ngde">Exported from <code class="ngde">@angularity/command-flow/debugger</code><ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="exported-from-angularitycommand-flowdebugger"></ng-doc-heading-anchor></h3><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/command-flow-debugger/provideCommandFlowDebugger" class="ng-doc-code-anchor ngde">provideCommandFlowDebugger</a></code><p class="ngde">Provides a debugger that logs commands and events to the console to an application.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-debugger/COMMAND_ID_GENERATOR" class="ng-doc-code-anchor ngde">COMMAND_ID_GENERATOR</a></code><p class="ngde">Injection token for a function that generates a unique identifier for a command.</p><p class="ngde">By default, the identifier is a number that is incremented for each command.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/command-flow-debugger/COMMAND_FLOW_DEBUGGER_FILTER" class="ng-doc-code-anchor ngde">COMMAND_FLOW_DEBUGGER_FILTER</a></code><p class="ngde">Injection token for a filter function that determines which commands and events should be logged by the debugger.</p><p class="ngde">By default, all commands and events are logged.</p></li></ul>',E=(()=>{let e=class e extends s{constructor(){super(),this.pageType="guide",this.pageContent=C,this.page=o,this.demoAssets=p}};e.\u0275fac=function(a){return new(a||e)},e.\u0275cmp=l({type:e,selectors:[["ng-doc-page-5lmmckfr"]],features:[t([{provide:s,useExisting:e},f,o.providers??[]]),r],decls:1,vars:0,template:function(a,Q){a&1&&i(0,"ng-doc-page")},dependencies:[g],encapsulation:2,changeDetection:0});let c=e;return c})(),P=[d(n({},(0,u.isRoute)(o.route)?o.route:{}),{path:"",component:E,title:"Command Flow"})],N=P;export{E as PageComponent,N as default};
